  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} manager classé.": "初始评分 1500，每场与其他经理的正式比赛都会使其升降（对手评分越高，获胜收益越大）。对阵 AI 的比赛和友谊赛不计入。共 {0} 名经理上榜。",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} managers classés.": "初始评分 1500，每场与其他经理的正式比赛都会使其升降（对手评分越高，获胜收益越大）。对阵 AI 的比赛和友谊赛不计入。共 {0} 名经理上榜。",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs. Barrage et relégation seulement s'il existe un championnat juste en dessous (couleurs et légende l'indiquent). Ce panneau résume votre position et l'écart avec les places clés.": "排名先按胜场，再按净胜分排序。第 1 至 4 名：季后赛。只有当下方紧邻存在联赛时才有附加赛和降级（以颜色和图例标示）。此面板概括你的位置以及与关键名次的差距。",
  " ; s'il existe un championnat ouvert juste en dessous, le 10e est ": "；若下方紧邻有开放的联赛，第 10 名",
  "relégué": "降级",
  ", puis le 9e, et avec trois championnats en dessous le 7e et le 8e jouent un ": "，然后是第 9 名；若下方有三个联赛，第 7 名和第 8 名进行",
  ". Seules les zones réellement en jeu sont colorées. Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": "。只有真正相关的区域才会着色。每支球队都会显示近期状态。“季后赛争夺”面板概括你的位置、战绩以及与关键名次的差距。",
  "Play-offs · le champion monte": "季后赛 · 冠军升级",
  "Play-offs · le champion monte en {0}": "季后赛 · 冠军升入{0}",
  "Relégation directe (10e)": "直接降级（第 10 名）",
  "Avance sur la {0}e (barrage)": "领先第 {0} 名（附加赛）",
  "Avance sur la {0}e (relégation)": "领先第 {0} 名（降级）",
  "Retard sur la {0}e (barrage)": "落后第 {0} 名（附加赛）",
  "Retard sur la {0}e (maintien)": "落后第 {0} 名（保级）",
  "-0 pour": "-0 对",
