  ", 5 et 6 maintien direct, 7 et 8": "，第 5、6 名直接保级，第 7、8 名",
  ", agrandissable palier par palier depuis cet onglet, accélère cette progression. À ses 18 ans, une décision est requise pour chaque jeune : le promouvoir dans l'effectif pro (il dévoile alors son vrai palier de potentiel) ou le libérer définitivement. Sans décision avant la saison suivante, il est automatiquement libéré. L'historique des jeunes promus reste visible en bas de la page.": "（可在此标签页逐级扩建）会加快这一进程。年满 18 岁时，每名年轻球员都需要你做出决定：将他提拔进职业阵容（届时会揭晓他真实的潜力等级），或将他永久放弃。若在下个赛季前未做决定，他将被自动放弃。已提拔年轻球员的历史记录保留在页面底部。",
  ", au moment où commence l'émission d'avant-match.": "，即赛前节目开始时。",
  "d'abord (liseré orange et petit « 5 »), puis la rotation, puis la réserve (nom estompé), d'après la feuille de match actuelle ; cliquez un titre de colonne pour trier toute la liste. Pour chacun : poste, potentiel, âge, taille, salaire, forme, motivation et évaluation des derniers matchs. Le menu": "排在最前（橙色边框和小“5”字），然后是轮换球员，再是替补（名字变暗），依据当前的比赛名单；点击列标题可对整个列表排序。每名球员显示：位置、潜力、年龄、身高、薪水、状态、积极性以及近几场比赛的评分。菜单",
  ", de plus en plus vite si vous la gardez plusieurs matchs de suite : +6, +8, +10, puis +12 par match. L'entraînement collectif": "，如果你连续多场保持该战术，增长会越来越快：每场 +6、+8、+10，然后 +12。集体训练",
  ", du plus modeste au plus rare :": "，从最普通到最稀有：",
  ", gérer l'": "，管理",
  ", le {0}": "，{0}",
  ", mais doucement : rien les 2 premiers matchs d'absence, puis -2, -4 et au maximum -6 par match. Revenir à une tactique délaissée la fait remonter progressivement, jamais d'un coup.": "，但很缓慢：缺席的前 2 场不下降，之后每场 -2、-4，最多 -6。重新使用被搁置的战术会使其逐渐回升，而不是一下子恢复。",
  ", mais ils le prennent moins que d'autres zones.": "，但他们受到的影响比其他区域小。",
  ", Mécontents": "，不满",
  ", plus floue, alignée sur les mêmes paliers :": "，更模糊，与相同的等级对应：",
