  ". Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": "。每支球队都会显示近期状态。“季后赛争夺”面板概括你的位置、战绩以及与关键名次的差距。",
  ". Chaque jour d'entraînement sur cet aspect ajoute {0} de connaissance tactique, crédités au prochain match où il est effectivement joué (voir Connaissance tactique).": "。在该方面每训练一天，会增加 {0} 点战术熟练度，在下一场实际使用该战术的比赛中计入（见战术熟练度）。",
  ". Entre deux matchs, votre travail : préparer les": "。两场比赛之间，你的工作是：准备",
