  "'adminTeamName' doit correspondre à l'un des noms de 'teamNames'.": "'adminTeamName' 必须与 'teamNames' 中的某个名称一致。",
  "'adminTeamName' doit être une chaîne non vide si fourni.": "如提供 'adminTeamName'，它必须是非空字符串。",
  "'amount' (nombre non nul, positif ou négatif) requis.": "需要 'amount'（非零数字，可正可负）。",
  "'color' est requis.": "需要 'color'。",
  "'dataUrl' requis (ou null pour retirer le logo personnalisé).": "需要 'dataUrl'（或传 null 以移除自定义队徽）。",
  "'isPaying' (booléen) requis.": "需要 'isPaying'（布尔值）。",
