  "'patch' ne contient aucun champ reconnu (offensivePriorities/defense/rhythm/lineup/tacticalTier/screenDefense/helpDefense/watchAssignments/postDefense/closeoutStyle/offRebStyle/endgameManagement).": "'patch' 不包含任何可识别的字段（offensivePriorities/defense/rhythm/lineup/tacticalTier/screenDefense/helpDefense/watchAssignments/postDefense/closeoutStyle/offRebStyle/endgameManagement）。",
  "'pattern' est requis.": "需要 'pattern'。",
