  "'team' (index d'équipe valide) requis.": "需要 'team'（有效的球队索引）。",
  "'team' et 'league' sont requis.": "需要 'team' 和 'league'。",
  "'teamName' (chaîne non vide) requis.": "需要 'teamName'（非空字符串）。",
  "'teamNames' doit être un tableau de 1 à 10 noms de club.": "'teamNames' 必须是包含 1 到 10 个俱乐部名称的数组。",
