  "\"Ça fait des semaines que je suis sur le banc sans la moindre explication, je demande à partir\", lâche {player}.": "“我已经连续几周坐在板凳上，没有任何解释，我要求离队。”{player} 说道。",
  "\"J'ai besoin de retrouver du temps de jeu ailleurs\", déclare {player}, visiblement lassé de la situation.": "“我需要去别的地方重新获得上场时间。”{player} 表示，显然已经对现状感到厌倦。",
  "\"Je ne me sens plus utile ici, il est temps d'envisager un nouveau projet\", confie {player} à la presse.": "“我觉得自己在这里已经没有用武之地了，是时候考虑新的发展了。”{player} 向媒体透露。",
  "\"Le club connaît ma position, je souhaite être transféré au plus vite\", affirme {player}.": "“俱乐部清楚我的立场，我希望尽快被交易。”{player} 表示。",
  "« À mi-parcours, cette victoire contre Adversaire test confirme qu'on est sur la bonne trajectoire, il reste encore la moitié de la saison pour la confirmer. On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié. »": "“赛季过半，这场对阵测试对手的胜利证明我们走在正确的轨道上，但还有半个赛季需要去证明。我们会延续现在的工作方式，并在下半程做一些战术调整。”",
  "« Comme l'appareil » suit le mode clair ou sombre de ton ordinateur ou de ton téléphone.": "“跟随设备”会跟随你电脑或手机的浅色或深色模式。",
  "({0}-{1}, en cours)": "（{0}-{1}，进行中）",
  "({1} pts) et": "（{1} 分）和",
  "({1}) · {2} d'efficacité sur {3}": "（{1}）· {3} 上的效率为 {2}",
  "({3} pts).": "（{3} 分）。",
  "(aux deux niveaux) : Standard garde le comportement habituel. Adaptatif ajoute un vrai garbage time dès 10 points d'écart à partir du 3e quart-temps (au 4e quart-temps, à 18 points d'écart, les titulaires sortent pour ménager leur forme), et accélère légèrement le rythme dans les 5 dernières minutes d'un match serré.": "（两个级别均适用）：标准保持常规行为。自适应会在第 3 节起分差达到 10 分时加入真正的垃圾时间（第 4 节分差达到 18 分时，首发球员下场以保存体能），并在焦灼比赛的最后 5 分钟略微加快节奏。",
  "(avec une petite jauge à 10 crans dans l'Effectif ; survolez le nom du palier pour voir son rang de 1 à 10). Un jeune joueur encore faible mais à fort potentiel peut, bien entraîné, dépasser largement un joueur déjà bon dont le potentiel est presque atteint.": "（“阵容”中带有一个 10 格的小量表；将鼠标悬停在等级名称上可查看其 1 到 10 的排名）。一名目前实力较弱但潜力很高的年轻球员，经过良好训练，可以远远超过一名已经不错但潜力几乎已达上限的球员。",
  "(c'est vous !)": "（就是你！）",
  "(cinq moments clés de la saison : début, mi-saison, fin de saison régulière, demi-finale puis finale des play-offs). Chaque interview pose deux questions, avec un ton à choisir pour chacune : Agressif amplifie le résultat (meilleur gain en cas de victoire, pire perte en cas de défaite), Mesuré reste sûr et modéré, Humble plafonne le gain en cas de victoire mais est le seul ton qui tourne une défaite en effet positif. Toute l'équipe est concernée. Ignorer l'interview (possible pendant 3 jours) n'a aucun effet. Un remplaçant qui ne joue quasiment jamais perd un peu de motivation chaque semaine, davantage s'il est meilleur que le titulaire de son poste.": "（赛季的五个关键时刻：赛季初、赛季中期、常规赛结束、季后赛半决赛和总决赛）。每次采访有两个问题，每个问题可选择一种语气：激进会放大结果（胜利时收益更大，失利时损失更大），克制稳妥适中，谦逊会限制胜利时的收益，但它是唯一能把失利转为正面效果的语气。影响全队。忽略采访（3 天内可以回应）没有任何效果。几乎从不上场的替补每周会损失一点积极性，如果他比同位置的首发更强，损失会更多。",
  "(display-mode: standalone)": "(display-mode: standalone)",
  "(Division {0})": "（{0} 级联赛）",
  "(en cours)": "（进行中）",
  "(en direct)": "（直播中）",
  "(face à n'importe quel autre joueur ; pour un adversaire, seules ses caractéristiques révélées sont comparées) et": "（可与任何其他球员对比；对于对手球员，只比较已揭示的属性）和",
  "(interrupteur manuel temporaire, en attendant un vrai système de paiement)": "（临时手动开关，在正式支付系统上线前使用）",
  "(marché, jeunes, staff) et les finances du club.": "（市场、青训、工作人员）以及俱乐部财务。",
