  "(ne fonctionne pas à chaque fois ; vous pouvez aussi le vendre ci-dessous)": "（并非每次都有效；你也可以在下方出售他）",
  "(onglet Académie de jeunes, candidats comme jeunes déjà signés) n'affichent qu'une estimation à": "（“青训营”标签页，包括候选球员和已签约的年轻球员）只显示估计值，精度为",
  "(onglet Staff) pour faire une séance vidéo sur un adversaire (une par jour, une seule fois par adversaire et par saison) : elle révèle définitivement une partie de ses caractéristiques, plus ou moins selon le niveau de l'analyste. L'": "（“工作人员”标签页）对对手进行录像分析（每天一次，每个赛季每个对手只能一次）：它会永久揭示对手的部分属性，揭示多少取决于分析师的等级。",
  "(onglet Staff), renouvelés au fil du temps, comme le marché des transferts. Enchérissez sur celui qui vous intéresse ; au bout de {0} jours réels, le plus offrant à ce moment-là l'emporte. Sa mise gagnante devient son": "（“工作人员”标签页），会像转会市场一样随时间刷新。对你感兴趣的人出价；{0} 个真实日后，届时出价最高者获胜。他的中标价将成为他的",
  "(ou \"Voir le direct\" sur le Tableau de bord et le Calendrier) : tableau d'affichage avec la courbe d'écart, fil du match, carte des tirs filtrable, face-à-face des deux équipes et feuille de match. Une émission d'avant-match démarre 5 minutes avant le coup d'envoi, et à la mi-temps un bouton \"Voir l'émission\" ouvre l'émission de la pause. Pendant un direct, le Tableau de bord propose \"Voir le live\" à la place des ordres.": "（或仪表盘和赛程中的“观看直播”）：带分差曲线的记分牌、比赛动态、可筛选的投篮分布图、两队对比和技术统计。开赛前 5 分钟会开始赛前节目，中场休息时“观看节目”按钮会打开中场节目。直播期间，仪表盘会显示“观看直播”而不是指令。",
  "(prefers-color-scheme: light)": "(prefers-color-scheme: light)",
  "(préparé) ●": "（已准备）●",
  "(quand elle existe pour votre ligue) est un tableau à élimination directe, un tour chaque jeudi à 20:00. L'onglet Coupe montre votre parcours (tour atteint, victoires, pastille par tour), les matchs de chaque tour (boutons de tour en haut, filtres Tous et À jouer, votre match en premier, clubs exemptés résumés en une ligne) et l'arbre de la phase finale à partir des 8es de finale. Les ordres de Coupe se préparent comme ceux du championnat.": "（如果你的联赛有杯赛）采用单场淘汰制，每周四 20:00 进行一轮。“杯赛”标签页显示你的晋级之路（到达的轮次、胜场、每轮徽章）、每轮的比赛（顶部的轮次按钮、“全部”和“待进行”筛选、你的比赛排在最前、轮空的俱乐部汇总为一行），以及从 16 强开始的淘汰赛对阵图。杯赛指令的准备方式与联赛相同。",
  "(semaine {1})": "（第 {1} 周）",
  "(style de jeu, zones de tir, cinq de départ suggéré, plan de match) est un rapport avancé.": "（打法风格、投篮区域、建议首发五人、比赛计划）是一份高级报告。",
  "(tir, passe, défense, etc.) à travailler et les postes concernés : ce n'est pas un choix joueur par joueur. Un joueur en profite s'il occupe l'un des postes choisis, proportionnellement au temps qu'il a joué à ce poste, CUMULÉ sur tous les matchs de la semaine (mardi et samedi en championnat, plus le jeudi en Coupe), pas seulement le dernier ({0} minutes cumulées = 100% de l'entraînement, {1} minutes = 50%, etc.) ; s'il n'a pas joué au bon poste de la semaine, aucun fondamental ne progresse (seul le déclin lié à l'âge continue de s'appliquer normalement). L'entraînement se déclenche automatiquement une fois par semaine, le lundi à 6h, heure de Paris (en même temps que la mise à jour économique) : c'est à ce moment-là que les compteurs de temps de jeu de cet onglet repartent à 0 pour la semaine suivante. Le poste (plus ou moins naturel pour la compétence) et le gabarit (un grand progresse plus vite en jeu intérieur/rebond/contre, un petit en dribble/agilité/tir extérieur/passe) influencent aussi la vitesse de progression. Étendre l'entraînement à plus de postes forme plus de joueurs mais dilue le rendement de tous. Le Physique et le Mental, eux, ne se travaillent plus directement : le Physique évolue à peine tout seul au fil de la carrière, tandis que le Mental progresse nettement et continuellement, jusqu'à un âge avancé — avec un petit coup de pouce quand un fondamental lié est entraîné (ex. le Jeu intérieur aide un peu la Force). Le staff (entraîneur) se gère depuis l'onglet": "（投篮、传球、防守等）以及涉及的位置：这不是逐个球员的选择。球员如果打的是所选位置之一，就能受益，受益程度与他在该位置上的上场时间成正比，按本周所有比赛累计（联赛周二和周六，杯赛再加周四），而不仅仅是最后一场（累计 {0} 分钟 = 100% 训练效果，{1} 分钟 = 50%，以此类推）；如果他本周没有在正确的位置上场，基础能力不会提升（只有年龄导致的衰退照常进行）。训练每周自动进行一次，时间为巴黎时间周一早上 6 点（与经济更新同时）：此时本标签页的上场时间计数器会清零，进入下一周。位置（对该技能而言是否自然）和体型（高个球员在内线进攻/篮板/盖帽上进步更快，矮个球员在运球/灵活性/外线投篮/传球上进步更快）也会影响进步速度。把训练扩展到更多位置能训练更多球员，但会稀释每个人的收益。身体和心理不再直接训练：身体在职业生涯中几乎不会自行变化，而心理则会明显且持续地提升，直到较大年龄——当相关基础能力被训练时还会得到小幅提升（例如内线进攻会稍微帮助力量）。工作人员（教练）在以下标签页中管理：",
  "(voir Entraînement), plafonnée à 100. S'entraîner ne la fait pas baisser.": "（见训练），上限为 100。训练不会使其下降。",
  "(vos achats et vos ventes en cours, les enchères où vous avez été dépassé en premier).": "（你正在进行的买入和卖出，以及你最先被超越的竞拍）。",
  "(play-offs compris) ; en Coupe, un tour chaque": "（含季后赛）；杯赛每",
  ". La mise à jour économique (salaires, recettes) et l'entraînement des fondamentaux ont lieu dans la nuit du dimanche au lundi. Entre deux matchs, votre travail : préparer les": "。经济更新（薪水、收入）和基础能力训练在周日到周一的夜间进行。两场比赛之间，你的工作是：准备",
