  ") en une mi-temps": "）在半场内",
  ") et deux boutons, Recruter ou Ignorer. Un prospect signé rejoint l'académie (15 places maximum) et progresse automatiquement chaque jour, sans match ni choix d'entraînement.": "）以及两个按钮：签约或忽略。签约的新秀会加入青训营（最多 15 个名额），并每天自动成长，无需比赛或选择训练。",
  "), eux, ne sont recalculés qu'au début de chaque nouvelle saison, d'après le niveau de chaque joueur à son poste. Vous pouvez vendre l'intégralité de votre effectif si vous le souhaitez, mais un match sans assez de joueurs pour composer un cinq de départ est perdu par forfait (20-0).": "）只在每个新赛季开始时，根据每名球员在其位置上的水平重新计算。如果你愿意，可以卖掉整个阵容，但如果比赛时球员不足以组成首发五人，将判负（20-0）。",
  "), composer le cinq et la tactique dans l'onglet Ordres, puis valider. Vous pouvez aussi préparer plusieurs journées à l'avance (voir": "），在“指令”标签页中安排首发五人和战术，然后确认。你也可以提前准备多轮比赛（见",
