  "21 ans et moins": "21 岁及以下",
  "22–25 ans": "22–25 岁",
  "26–29 ans": "26–29 岁",
  "29 caractéristiques (0 à 99) : Tir à mi-distance, Tir à 3 points, Jeu intérieur, Passe, Rebond, Contre, Dribble, Agilité, Défense extérieure, Défense intérieure, Mental, Endurance, Lancer franc, Pénétration, Création de tir, Interceptions, Puissance, Concentration, Anticipation, Leadership, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision. Sur chacune, plus le chiffre est élevé, mieux c'est, sans exception. La couleur donne le niveau en un coup d'œil : rouge en dessous de 45, grise de 45 à 64, verte de 65 à 79, dorée à partir de 80 (niveau élite).": "29 项属性（0 至 99）：中距离投篮、三分投篮、内线进攻、传球、篮板、盖帽、运球、灵活性、外线防守、内线防守、心理、耐力、罚球、突破、投篮创造、抢断、力量、专注、预判、领导力、速度、加速、强壮、弹跳、决策、冷静、决心、纪律性和视野。每一项都是数值越高越好，没有例外。颜色可让你一眼看出水平：45 以下为红色，45 至 64 为灰色，65 至 79 为绿色，80 及以上为金色（精英水平）。",
  "2PTS": "2分",
