  "5 paliers, du plus frais (90-100) au plus épuisé (0-39, risque de blessure nettement accru). Baisse après chaque match selon le temps de jeu, remonte de 10 points par jour sans match (15 avec l'entraînement collectif Récupération).": "5 个等级，从最充沛（90-100）到最疲惫（0-39，受伤风险明显增加）。每场比赛后根据上场时间下降，无比赛日每天恢复 10 点（选择“恢复”集体训练时为 15 点）。",
