  "Achetez des joueurs aux enchères ou mettez les vôtres en vente. Chaque enchère dure 1 jour réel, et les autres clubs peuvent surenchérir jusqu'au bout. Filtres par poste, âge, potentiel, prix et caractéristiques, suivi de vos enchères en haut de page.": "通过竞拍购买球员，或将你的球员挂牌出售。每次竞拍持续 1 个真实日，其他俱乐部可以一直加价到最后一刻。可按位置、年龄、潜力、价格和属性筛选，你的竞拍会在页面顶部追踪显示。",
