  "Agrandissement du Centre de formation refusé.": "青训中心扩建被拒绝。",
  "Agrandissez votre salle place par place pour accueillir plus de spectateurs (brique Agrandir la salle : chaque type de gradin a son prix par place et son nombre maximum de places), et réglez le prix du billet CATÉGORIE PAR CATÉGORIE : gradins populaires, tribune couverte et loges VIP n'ont ni la même capacité, ni la même tolérance au prix. Seuls les matchs à domicile rapportent une recette. L'humeur des supporters influence le remplissage et la tolérance au prix. D'autres infrastructures sont proposées, chacune sur 5 niveaux comme le centre de formation : Boutique des supporters (revenu fixe chaque semaine), Station TV (revenu fixe chaque semaine), Salle de musculation (réduit le risque de blessure) et Espace bien-être (réduit la fatigue en match).": "逐个座位扩建你的球馆以容纳更多观众（“扩建球馆”模块：每种看台都有各自的单座价格和最大座位数），并按类别分别设置票价：普通看台、有顶看台和 VIP 包厢的容量和对价格的承受度都不同。只有主场比赛才有门票收入。球迷情绪会影响上座率和对价格的承受度。还有其他设施可供选择，每种与青训中心一样有 5 个等级：球迷商店（每周固定收入）、电视台（每周固定收入）、力量训练房（降低受伤风险）和康体中心（减少比赛中的疲劳）。",
