  "Changement de couleurs de maillot extérieur refusé côté serveur.": "更改客场球衣颜色被服务器拒绝。",
  "Changement de couleurs de maillot refusé côté serveur.": "更改球衣颜色被服务器拒绝。",
  "Changement de logo refusé côté serveur.": "更改队徽被服务器拒绝。",
  "Changement de maillot extérieur refusé côté serveur.": "更改客场球衣被服务器拒绝。",
  "Changement de maillot refusé côté serveur.": "更改球衣被服务器拒绝。",
  "Changement de motif de maillot extérieur refusé côté serveur.": "更改客场球衣图案被服务器拒绝。",
  "Changement de motif de maillot refusé côté serveur.": "更改球衣图案被服务器拒绝。",
  "Changement de statut club refusé côté serveur.": "更改俱乐部状态被服务器拒绝。",
  "Changer d'analyste vidéo": "更换录像分析师",
  "Changer d'entraîneur": "更换教练",
  "Changer de recruteur": "更换球探",
  "Changer le logo": "更换队徽",
  "Chaque annonce compare le prix à une valeur estimée (Bonne affaire, Prix correct, Au-dessus de sa valeur). Une enchère gagnée s'ajoute immédiatement à votre masse salariale : vérifiez votre budget avant de vous engager.": "每条挂牌都会将价格与估计身价进行比较（划算交易、价格合理、高于其身价）。竞拍成功后会立即计入你的工资总额：出价前请确认你的预算。",
  "Chaque changement est déjà enregistré automatiquement. « Enregistrer » confirme l'enregistrement auprès du serveur.": "每次更改都已自动保存。“保存”用于向服务器确认保存。",
  "à chaque jour de repos (jour sans match) : soit préparer une nouvelle tactique, soit privilégier la récupération physique de l'équipe.": "在每个休息日（无比赛日）：要么准备新战术，要么优先恢复球队体能。",
  "Le club choisit": "俱乐部选择",
  "Chaque jour, le club travaille un programme parmi les 13 fondamentaux (tir à 3 points, rebond, défense extérieure...) et un ou plusieurs postes à qui l'appliquer. Cibler un seul poste donne le plein rendement ; l'étendre à toute l'équipe touche plus de joueurs mais dilue l'effet. Le Physique et le Mental évoluent, eux, tout seuls au fil de la carrière, indépendamment de ce programme.": "俱乐部每天从 13 项基础能力（三分投篮、篮板、外线防守……）中选择一项训练计划，并指定一个或多个适用的位置。只针对一个位置可获得全部效果；扩展到全队能覆盖更多球员，但效果会被稀释。身体和心理属性则会在职业生涯中自行发展，与此计划无关。",
  "Chaque match se joue à son heure, que vous le regardiez ou non. Connecté, suivez-le depuis l'onglet": "每场比赛都会按时进行，无论你是否观看。在线时，可在以下标签页中关注比赛：",
  "Chaque nom de club doit être une chaîne non vide.": "每个俱乐部名称都必须是非空字符串。",
  "Chaque prospect affiche une estimation de potentiel (Espoir, Grand espoir ou Prodige) et se signe directement, sans enchère ni négociation, contrairement au marché des transferts.": "每位新秀都会显示潜力估计（新星、大有前途或天才），可直接签约，无需竞拍或谈判，这与转会市场不同。",
  "Chaque variation d'ambiance est journalisée ici avec son motif exact : résultat de match, prix du billet, interview de jalon, demande de transfert, signal ou verdict d'objectif de saison.": "每次氛围变化都会在此记录并注明确切原因：比赛结果、票价、关键节点采访、转会申请、赛季目标的信号或结论。",
