  "Choisissez 3 priorités offensives pour les deux équipes avant le coup d'envoi.": "开赛前为两支球队各选择 3 个进攻重点。",
  "Choisissez exactement 3 systèmes offensifs parmi 10 (Pick & Roll, Transition rapide, Post-up, Isolation...). Chacun modifie la répartition des tirs tentés (intérieur/mi-distance/3 points), les pertes de balle et le rythme.": "从 10 种进攻体系中恰好选择 3 种（挡拆、快攻、背身单打、单打……）。每种体系都会改变出手分布（内线/中距离/三分）、失误和比赛节奏。",
