  "Connaissance tactique": "战术熟练度",
  "Connaissance tactique : chaque option jouée monte de +6 à +12 par match, +4 par jour d'entraînement dessus ; une option délaissée ne baisse qu'à partir du 3e match d'absence (-2, -4, puis -6 au maximum). Le détail est dans le Guide.": "战术熟练度：每个被使用的战术选项每场比赛提升 +6 至 +12，每训练一天提升 +4；被闲置的选项从缺席第 3 场比赛起才会下降（-2、-4，最多 -6）。详情见指南。",
  "Conseil : attaquez la raquette sans crainte, pénétrez et finissez au panier plutôt que de vous contenter du tir extérieur.": "建议：大胆冲击禁区，突破后在篮下终结，而不是满足于外线投篮。",
  "Conseil : envoyez du monde au rebond offensif, les secondes chances seront disponibles.": "建议：多派人抢进攻篮板，二次进攻机会会很多。",
  "Conseil : évitez la finition en force au cercle, privilégiez le tir extérieur ou la passe après pénétration (kick-out) plutôt que le layup contesté.": "建议：避免在篮下强行终结，突破后优先选择外线投篮或分球（kick-out），而不是被干扰的上篮。",
  "Conseil : forcez la pénétration balle en main et jouez agressif vers le cercle pour provoquer des fautes et aller sur la ligne des lancers francs.": "建议：持球强攻突破，积极冲击篮筐以制造犯规、多上罚球线。",
  "Conseil : ne comptez pas sur les lancers francs, il faudra scorer au jeu plutôt que provoquer la faute.": "建议：别指望罚球，你需要靠运动战得分，而不是制造犯规。",
  "Conseil : ne surinvestissez pas le rebond offensif, repliez-vous plus tôt pour limiter leur contre-attaque.": "建议：不要过度投入进攻篮板，尽早回防以限制他们的快攻。",
  "Conseil : sécurisez la balle et limitez les passes risquées pour ne pas les lancer en contre-attaque.": "建议：保护好球，减少冒险传球，以免给他们快攻机会。",
