  "Jusqu'à 150 000 €": "最高 150 000 €",
  "Jusqu'à 3 affectations poste + focus (empêcher le post-up, coller sur les pénétrations, harceler le tir extérieur, priorité au rebond, couper du ballon). Chaque focus donne un bonus défensif ciblé, avec une petite contrepartie ailleurs pour le défenseur concerné.": "最多 3 项位置分配 + 防守重点（阻止背身单打、紧贴防守突破、干扰外线投篮、优先抢篮板、断绝传球）。每项重点都会提供针对性的防守加成，但相关防守球员在其他方面会有少许代价。",
  "Jusqu'à 300 000 €": "最高 300 000 €",
  "Jusqu'à 50 000 €": "最高 50 000 €",
  "Jusqu'où le joueur peut encore progresser, jamais en chiffre : un palier parmi 10, de Débutant à Générationnel (Prospect, Joueur correct, Solide, Starter, Très bon joueur, Star, All-Star, Superstar). Les jeunes de l'académie n'affichent qu'une estimation : Espoir, Grand espoir ou Prodige.": "球员还能进一步成长的空间，从不以数字显示：共 10 个等级，从新手到世代级（潜力股、合格球员、稳健、首发级、优秀球员、球星、全明星、超级巨星）。青训营的年轻球员只显示估计：新秀、明日之星或天才。",
