  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "对手无法派出完整首发五人：你将在预定时间自动以弃权获胜（20-0）。",
  "L’affiche": "焦点之战",
  "L'alchimie (0 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 25), Tensions dans le groupe (25-44), Cohésion correcte (45-64), Bonne cohésion (65-84), Alchimie parfaite (85 et plus).": "化学反应（0 到 100，显示在仪表盘和阵容页顶部）衡量球队的凝聚力。它在比赛中影响整支球队，范围从 -6%（更衣室分裂）到 +6%（化学反应完美）。等级：更衣室分裂（低于 25）、团队关系紧张（25-44）、凝聚力尚可（45-64）、凝聚力良好（65-84）、化学反应完美（85 及以上）。",
  "L'ambiance du club": "俱乐部氛围",
  "L’attaque tourne à plein régime.": "进攻火力全开。",
