  "L’AVANT-MATCH": "赛前",
  "L'effectif jeunes est déjà complet (15 stagiaires).": "青年队已满（15 名学员）。",
  "L'émission de la mi-temps": "半场节目",
  "l'emporte de": "领先",
  "L'entraîneur n'a aucun effet sur les matchs : il accélère uniquement la progression à l'entraînement (+6% par niveau). On ne l'achète plus à prix fixe : plusieurs candidats de niveaux variés sont proposés en permanence sur un": "教练对比赛没有任何影响：他只会加快训练中的成长速度（每级 +6%）。教练不再以固定价格购买：多位不同等级的候选人会持续出现在一个",
  "L'entre-deux est remporté par {0}.": "{0} 赢得跳球。",
  "L'humeur des supporters (0 à 100, onglet dédié) influence le remplissage de votre salle et la tolérance au prix du billet : des supporters contents viennent plus facilement et acceptent des prix plus élevés. Elle évolue avec chaque résultat (victoire ou défaite, à domicile ou à l'extérieur), vos tons en interview de jalon, et dérive lentement selon que le prix des billets est jugé raisonnable ou non.": "球迷情绪（0 到 100，有专门的标签页）会影响球馆的上座率以及对票价的容忍度：心情愉快的球迷更愿意到场，也能接受更高的票价。它会随每场比赛结果（胜或负、主场或客场）、你在里程碑采访中的语气而变化，并根据票价是否被认为合理而缓慢漂移。",
  "L'image de votre salle actuelle. Une salle plus grande accueille plus de spectateurs à chaque match à domicile, donc plus de recettes de billetterie.": "你当前球馆的外观。球馆越大，每场主场比赛能容纳的观众越多，门票收入也越高。",
  "L'objectif de saison": "赛季目标",
  "L'objectif est clair pour cette saison : on vise le haut de tableau, on ne se fixe aucune limite.": "本赛季目标很明确：我们瞄准积分榜前列，不给自己设限。",
  "L'objectif est de construire une équipe solide et de rester compétitifs sur la durée de la saison, sans se fixer de chiffre précis pour l'instant.": "目标是打造一支稳健的球队，在整个赛季保持竞争力，目前不设定具体的数字。",
  "L'onglet": "标签页",
  "La": "​",
  "La confiance du joueur, jamais liée à la fatigue. Alimentée par le ton choisi lors des interviews de jalon (voir l'onglet Humeur des supporters) : Agressif amplifie le résultat, Mesuré reste modéré, Humble limite la casse en cas de défaite.": "球员的信心，与疲劳无关。受里程碑采访中所选语气的影响（参见“球迷情绪”标签页）：“激进”会放大结果，“克制”保持温和，“谦逊”在输球时能减少损失。",
  "La Coupe": "杯赛",
  "La Coupe n'existe que pour la ligue multi-manager (elle n'est pas jouée en carrière solo pour l'instant).": "杯赛仅在多人经理联赛中存在（目前单人生涯模式中不进行杯赛）。",
  "La courbe apparaîtra après le premier événement.": "首个事件发生后将显示曲线。",
  "La courbe du budget apparaîtra après la première semaine.": "第一周结束后将显示预算曲线。",
  "La décision à 18 ans": "18 岁的决定",
  "la défaite": "失利",
