  "La feuille de match de l'adversaire est incomplète : vous gagnerez par forfait (20-0) si elle n'est pas réglée avant le coup d'envoi.": "对手的出场名单不完整：如果开赛前仍未设置，你将以弃权获胜（20-0）。",
  "la finale des play-offs": "季后赛总决赛",
