  "La liste des jeunes formés dans votre académie qui sont ensuite passés pro : un aperçu de ce que votre filière de formation a déjà produit pour le club.": "在你的青训营培养后转为职业球员的年轻人名单：展示你的青训体系已为俱乐部输送的人才。",
  "La plupart des joueurs se situent dans les paliers médians (Starter à All-Star) ; Superstar et Générationnel restent volontairement rares.": "大多数球员处于中等等级（首发级到全明星）；超级巨星和世代级被刻意设计得非常稀有。",
  "La routine conseillée avant chaque match : vérifier la forme des joueurs (": "每场比赛前的推荐流程：检查球员状态（",
