  "Le barrage de relégation a été calculé. Les play-offs commencent, un match à la fois, en direct, sur plusieurs jours réels.": "保级附加赛已结算。季后赛开始，每次一场比赛，现场直播，历时多个真实日。",
  "Le calendrier": "赛程",
  "Le calendrier sera généré pour les clubs déjà inscrits.": "将为已报名的俱乐部生成赛程。",
  "Le centre de formation": "青训中心",
  "Le champion est désormais connu, direction l'écran de fin de saison.": "冠军已经产生，前往赛季结束页面。",
  "Le championnat est lancé": "联赛已开赛",
  "Le classement avant la journée": "本轮开始前的排名",
  "Le classement s'affichera après les premiers matchs de championnat.": "首批联赛比赛结束后将显示排名。",
  "Le classement se départage par victoires puis par différence de points. Il est découpé en zones : places 1 à 4 qualifiées pour les": "排名先按胜场，再按分差决定。排名分为几个区域：第 1 至 4 名晋级",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs ; 5 et 6 : maintien ; 7 et 8 : barrage ; 9 et 10 : relégation. Ce panneau résume votre position et l'écart avec les places clés.": "排名先按胜场，再按分差决定。第 1 至 4 名：季后赛；第 5、6 名：保级成功；第 7、8 名：保级附加赛；第 9、10 名：降级。此面板汇总了你的位置以及与关键名次的差距。",
  "Le club est en quasi-faillite (budget : {0}, sous {1} depuis {2} semaine(s)) : tout l'effectif a été mis en vente forcée à 1 €. Direction l'onglet": "俱乐部濒临破产（预算：{0}，已连续 {2} 周低于 {1}）：全部球员已被强制以 1 € 挂牌出售。请前往标签页",
  "Le club est entre vos mains. Bonne saison, coach.": "俱乐部交给你了。祝你赛季顺利，教练。",
  "Le coup d'envoi est imminent.": "比赛即将开始。",
  "Le duel à suivre": "焦点对决",
  "Le duel de la soirée : {a} contre {b}.": "今晚的焦点对决：{a} 对阵 {b}。",
