  "Le marché des transferts": "转会市场",
  "Le match à suivre": "焦点比赛",
  "le match précédent": "上一场比赛",
  "Le même Centre de formation que dans l'onglet Salle, mais géré directement ici : agrandissable palier par palier, il accélère la progression automatique de tous vos jeunes tant qu'ils ont moins de 18 ans.": "与“球馆”标签页中相同的青训中心，但在这里直接管理：可逐级扩建，只要你的年轻球员未满 18 岁，就能加快他们的自动成长。",
  "Le moteur vise ces minutes et les ajuste seul en cas de blessure, de fautes ou de fatigue. Un poste en automatique garde la rotation habituelle.": "引擎会以这些分钟数为目标，并在出现伤病、犯规或疲劳时自动调整。设为自动的位置将保持常规轮换。",
  "Le n°1 en fin de saison gagne 1 mois de Premium": "赛季结束时排名第 1 可获得 1 个月 Premium",
  "Le nom de la ligue doit faire entre 2 et {0} caractères.": "联赛名称长度须为 2 至 {0} 个字符。",
  "Le nom de la salle contient des caractères non autorisés.": "球馆名称包含不允许的字符。",
  "Le nom de la salle doit faire entre 3 et {0} caractères.": "球馆名称长度须为 3 至 {0} 个字符。",
  "Le nom et la capacité de votre salle actuelle, avec un bouton Agrandir pour passer au palier suivant quand vous en avez les moyens (8 paliers en tout, du Petit gymnase à l'Arena nationale).": "你当前球馆的名称和容量，以及一个“扩建”按钮，在资金充足时可升级到下一级（共 8 级，从小型体育馆到国家级球馆）。",
  "Le numéro {0} est déjà retiré.": "{0} 号球衣已经退役。",
  "Le poste de {poste} est désormais pourvu.": "{poste}职位现已有人就任。",
  "Le potentiel indique jusqu'où un joueur peut encore progresser, pas sa qualité du moment. Il ne s'affiche jamais en chiffre : seulement un": "潜力表示球员还能进一步成长的空间，而不是他当前的水平。它从不以数字显示：只显示一个",
  "Le prix des billets se règle depuis l'onglet Salle, pas ici : ajustez-le pour équilibrer affluence et recettes.": "票价在“球馆”标签页中设置，而不是在这里：调整票价以平衡上座率和收入。",
  "Le roster complet du club en une seule liste, cinq de départ en tête, puis rotation et réserve : poste, potentiel, âge, salaire, forme, motivation et évaluation des derniers matchs. Cliquez sur un nom pour ouvrir la fiche du joueur (caractéristiques, saison, Comparer, Vendre).": "俱乐部完整名单一览，首发五人在前，然后是轮换和替补：位置、潜力、年龄、薪水、状态、士气以及近期比赛效率值。点击名字即可打开球员资料（属性、赛季、对比、出售）。",
