  "Le total sera ramené à 40 min en gardant ces proportions.": "总时间将按这些比例调整为 40 分钟。",
  "Le travail à l'entraînement toute la semaine a payé ce soir, je suis content d'avoir pu répondre présent.": "整周训练的付出在今晚得到了回报，我很高兴自己能挺身而出。",
  "Le trigramme doit faire 2 ou 3 lettres (A-Z).": "球队缩写须为 2 或 3 个字母（A-Z）。",
  "Le vrai potentiel d'un jeune reste caché derrière une estimation à 3 paliers jusqu'à sa promotion : la décision comporte donc une part de pari.": "年轻球员的真实潜力在被提拔之前一直隐藏在 3 级估计之后：因此这个决定带有一定的赌博成分。",
