  "Les ordres de Coupe se préparent comme ceux du championnat, depuis le Calendrier ou le sélecteur de journée de l'onglet Ordres.": "杯赛指令与联赛指令的设置方式相同，可在“赛程”或“指令”标签页的比赛日选择器中进行。",
  "Les play-offs sont en cours, sur plusieurs jours réels. Revenez pour votre prochain match, ou suivez leur progression ici.": "季后赛正在进行，历时多个真实日。请在你的下一场比赛时回来，或在这里关注赛事进展。",
  "Les play-offs vont commencer.": "季后赛即将开始。",
  "Les records s'écriront dès le premier match joué.": "纪录将从第一场比赛开始记录。",
  "Le poste d'un joueur suit ses caractéristiques : dès que sa note à un autre poste dépasse nettement celle de son poste actuel, il change de poste (une nouvelle vous prévient). Les salaires (masse salariale visible sur l'onglet": "球员的位置取决于他的属性：一旦他在另一位置的评分明显高于当前位置，就会改换位置（会有新闻通知你）。薪水（薪资总额可在标签页",
  "Les sponsors reviennent tous les 3 jours. Une meilleure réputation attire de plus grandes marques.": "赞助商每 3 天回来一次。声望越高，吸引的品牌越大。",
  "Les statistiques de ligue privée ne comptent ni dans les stats de carrière ni dans le classement des joueurs.": "私人联赛的数据不计入生涯数据，也不计入球员排名。",
