  "liste tous vos matchs de la saison, championnat et Coupe confondus, groupés par mois et triés par date et heure réelle. Filtres Tous, Domicile, Extérieur et À venir ; \"vs\" devant l'adversaire signifie à domicile, \"@\" à l'extérieur. À droite : la carte du prochain match (compte à rebours et bouton des ordres) et le bilan de la saison (bilan, classement, différence de points, domicile/extérieur, forme sur les 5 derniers matchs). Les horaires restent fixes, même au changement d'heure.": "列出你本赛季的全部比赛（联赛和杯赛），按月份分组，并按真实日期和时间排序。筛选项：全部、主场、客场和即将进行；对手前的“vs”表示主场，“@”表示客场。右侧：下一场比赛卡片（倒计时和指令按钮）以及赛季总结（战绩、排名、分差、主场/客场、近 5 场状态）。比赛时间固定不变，即使在夏令时切换时也是如此。",
