  "MENTAL": "心理",
  "Mental, Endurance, Lancer franc, Puissance, Concentration, Anticipation et Leadership alimentent chacune un mécanisme de match dédié. Le Mental améliore la réussite au tir dans le money time et limite les dégâts d'une mauvaise série. L'Endurance ralentit la fatigue EN MATCH du joueur. Le Lancer franc détermine directement la réussite aux lancers francs, la Concentration l'améliore encore un peu. La Puissance augmente les fautes provoquées près du panier. L'Anticipation renforce la pression défensive de toute l'équipe sur les extérieurs. Le Leadership du MEILLEUR joueur du cinq en jeu allège, pour toute l'équipe, le malus d'une mauvaise série de tirs manqués.": "心理素质、耐力、罚球、力量、专注力、预判和领导力各自对应一种专属的比赛机制。心理素质能提高关键时刻的投篮命中率，并减轻手感低迷的影响。耐力能减缓球员在比赛中的疲劳。罚球直接决定罚球命中率，专注力还能再略微提高。力量能增加在篮下制造的犯规。预判能增强全队对外线的防守压迫。场上五人中最佳球员的领导力，能为全队减轻连续投篮不中带来的惩罚。",
