  "Nom de la salle enregistré : {0}.": "球馆名称已保存：{0}。",
  "Nom, poste, taille et salaire des joueurs adverses sont toujours visibles, mais leurs caractéristiques restent cachées tant qu'elles n'ont pas été révélées : l'onglet Caractéristiques de l'effectif adverse n'affiche QUE les caracs révélées. Recrutez un": "对手球员的姓名、位置、身高和薪水始终可见，但其能力值在被揭示前保持隐藏：对手阵容的“能力值”标签页只显示已揭示的能力值。招募一名",
