  "Nouvelle faute technique pour {player} ({team}) : cumul de fautes disciplinaires, exclusion !": "{player}（{team}）再吃一次技术犯规：纪律性犯规累积，被驱逐出场！",
  "Nouvelle saison : les salaires ont été réévalués selon le niveau actuel de chaque joueur.": "新赛季：已根据每名球员当前水平重新评估薪水。",
