  "Objectif de la saison largement dépassé ({0} espéré) : l'équipe termine avec {1} ! Les supporters sont aux anges.": "大幅超额完成赛季目标（预期{0}）：球队最终取得{1}！球迷们欣喜若狂。",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec {1}. Les supporters sont déçus.": "未完成赛季目标（{0}）：球队最终取得{1}。球迷们很失望。",
  "Objectif de la saison manqué ({0}) : l'équipe termine avec une relégation. Les supporters sont déçus. ({1}).": "未完成赛季目标（{0}）：球队最终降级。球迷们很失望。（{1}）。",
  "Objectif de la saison rempli ({0}) : l'équipe termine avec {1}, exactement ce qui était demandé.": "完成赛季目标（{0}）：球队最终取得{1}，正好达到要求。",
