  "ok": "ok",
  "Oliveira": "Oliveira",
  "on": "on",
  "On a fait la moitié du chemin avec cette victoire contre {opponent}, mais rien n'est acquis, il reste encore beaucoup de travail avant la fin de saison.": "战胜{opponent}让我们走完了一半的路，但一切都还没有定局，赛季结束前还有很多工作要做。",
  "On aborde la suite avec humilité, chaque adversaire mérite le plus grand respect à ce stade de la saison.": "我们会以谦逊的态度迎接接下来的比赛，在赛季的这个阶段，每个对手都值得最大的尊重。",
  "On aborde la suite avec l'envie de corriger ce qui n'a pas fonctionné ces dernières semaines.": "接下来我们希望纠正最近几周出现的问题。",
  "On aborde la suite avec la certitude d'avoir le niveau pour aller loin, sans aucune pression particulière.": "我们深知自己有走得更远的实力，接下来会轻装上阵。",
  "On aborde la suite avec la même confiance, cette fin de saison régulière ne change rien à nos ambitions.": "我们会以同样的信心迎接接下来的比赛，常规赛这样收尾丝毫不会改变我们的雄心。",
  "On aborde la suite en sachant qu'il reste beaucoup de travail, on ne change rien à notre état d'esprit.": "我们知道还有很多工作要做，接下来我们的心态不会改变。",
  "On aborde la suite sereinement, en essayant de garder cette dynamique le plus longtemps possible.": "我们会平静地迎接接下来的比赛，尽可能长久地保持这股势头。",
  "On accepte cette élimination avec humilité et on va travailler encore plus dur pour revenir plus forts.": "我们以谦逊的态度接受这次出局，会更加努力训练，变得更强后再回来。",
  "On cherche un partenaire stable, pas un feu de paille.": "我们寻找的是稳定的合作伙伴，而不是昙花一现。",
  "On compte énormément sur {player} pour tirer l'équipe vers le haut, c'est un joueur fait pour ce genre de responsabilités.": "我们非常依赖{player}带领球队向上，他就是为承担这种责任而生的球员。",
  "On doit se remettre en question collectivement et travailler encore plus dur pour la seconde moitié de saison.": "我们必须集体反思，为下半赛季更加努力。",
  "On envoie un message clair à toute la ligue en éliminant {opponent} en demi-finale, la prochaine étape ne nous fait absolument pas peur.": "在半决赛淘汰{opponent}，我们向整个联赛发出了明确的信号，下一步我们丝毫不惧。",
  "On ne se fixe pas d'objectif chiffré, l'idée est de progresser ensemble match après match, en restant les pieds sur terre.": "我们不设定具体的数字目标，目的是一场接一场地共同进步，脚踏实地。",
  "On passe le cap de la mi-saison sur la meilleure dynamique possible, et {opponent} vient encore de le confirmer : personne ne veut vraiment nous affronter en ce moment.": "我们以最好的状态跨过赛季中点，{opponent}再一次证明了这一点：现在没人真的想和我们交手。",
  "On prépare la suite avec la même confiance, on n'a pas fait tout ce chemin pour s'arrêter en si bon chemin.": "我们会以同样的信心准备接下来的比赛，我们走了这么远，可不是为了半途而废。",
  "On savait qu'on était la meilleure équipe de la division, ce titre face à {opponent} en finale ne fait que le confirmer.": "我们早就知道自己是本级别最好的球队，决赛战胜{opponent}夺冠只是证实了这一点。",
  "On se retrouve après une courte pause…": "短暂休息后再见……",
  "On termine la saison régulière sur cette victoire contre {opponent}, et on aborde les échéances qui arrivent avec la plus grande confiance qui soit.": "我们以战胜{opponent}结束了常规赛，并以十足的信心迎接接下来的比赛。",
  "On termine la saison régulière sur une défaite décevante contre {opponent}, mais le bilan global de l'année reste ce qui compte le plus.": "我们以令人失望的输给{opponent}结束了常规赛，但全年的整体战绩才是最重要的。",
  "On tire un trait sur cette élimination et on prépare déjà la revanche pour la saison prochaine, sans complexe.": "我们翻过这次出局的一页，已经毫无顾虑地开始为下赛季的复仇做准备。",
  "On va analyser calmement cette élimination et en tirer les enseignements pour progresser encore.": "我们会冷静分析这次出局，从中吸取教训，继续进步。",
  "On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié.": "我们会延续现有的工作方式，并为下半赛季做一些战术调整。",
  "On va continuer à travailler humblement, rien n'est jamais acquis dans ce championnat.": "我们会继续谦虚地努力，在这个联赛中没有什么是板上钉钉的。",
  "On va préparer la suite avec sérieux, sans s'enflammer, il reste encore une marche à franchir.": "我们会认真准备接下来的比赛，不会得意忘形，还有一个台阶要跨越。",
  "On va préparer la suite pas à pas, sans se projeter trop vite sur la suite.": "我们会一步一步准备接下来的比赛，不会想得太远。",
  "On va revoir certains détails à l'entraînement pour repartir sur de meilleures bases en seconde moitié de saison.": "我们会在训练中检讨一些细节，以便下半赛季有更好的开局。",
  "On veut vous voir plus haut que ce que le CA demande.": "我们希望看到你的成绩超过董事会的要求。",
  "On vous suit sur l'objectif de la saison.": "我们在关注你的赛季目标进展。",
