  "Pénétration": "突破",
  "Pénétration, Création de tir, Interceptions, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision ont elles aussi leur mécanisme. La Pénétration aide à se créer un accès à la raquette. La Création de tir est le facteur principal de la qualité d'ouverture d'un tir. Les Interceptions pèsent dans le choix du voleur de balle. La Vitesse et l'Accélération déclenchent des contre-attaques et aident à battre son défenseur au premier pas. La Force et la Détente renforcent le rebond et le contre. La Décision réduit les pertes de balle ; la Vision améliore le choix du passeur. Le Sang-froid et la Détermination agissent comme le Mental. La Discipline réduit les fautes en défense ; un défenseur peu discipliné risque une faute antisportive, un défenseur peu serein une faute technique : deux techniques, deux antisportives, ou une de chaque dans le même match valent exclusion.": "突破、创造投篮、抢断、速度、爆发力、力量、弹跳、决策、冷静、决心、纪律和视野也各有其机制。突破有助于打开通往禁区的通道。创造投篮是决定投篮空位质量的主要因素。抢断影响由谁断球。速度和爆发力能发动快攻，并帮助第一步过掉防守者。力量和弹跳增强篮板和盖帽。决策减少失误；视野改善传球选择。冷静和决心的作用与心理相同。纪律减少防守犯规；纪律差的防守者可能吃到违体犯规，不够冷静的防守者可能吃到技术犯规：同一场比赛中两次技术犯规、两次违体犯规或各一次，都会被驱逐出场。",
