  "Chaque poste a sa carte sur le terrain : titulaire, remplaçant et réserviste. Les alertes (joueur hors poste, remplaçant plus fort que le titulaire, joueur aligné à deux postes) s'affichent directement sur la carte, et la liste de l'effectif à côté sert à convoquer les 12 joueurs du match.": "每个位置在球场上都有自己的卡片：首发、替补和预备。警告（球员打非本位、替补比首发更强、球员同时被安排在两个位置）会直接显示在卡片上，旁边的阵容列表用于选定本场比赛的12名球员。",
