  "La réputation du club auprès du public, bâtie sur les 5 dernières saisons : la division d'abord, puis le classement, les play-offs, la coupe et les montées. La saison la plus récente compte le plus. Mis à jour à chaque changement de saison.": "俱乐部在公众中的声望，基于最近5个赛季：首先是所在级别，其次是排名、季后赛、杯赛和升级。最近的赛季权重最大。每次换季时更新。",
