  "Deux types de programmes. Spécialisé : une seule compétence, à plein rendement. Polyvalent : deux compétences liées en même temps (par exemple Tir extérieur = Tir à mi-distance + Tir à 3 points), chacune progressant à 62 % du rythme d'un programme spécialisé. Au total, on progresse un peu plus (124 % contre 100 %), mais réparti sur deux compétences.": "训练计划有两种。专项：只练一项技能，全额效果。综合：同时练两项相关技能（例如外线投篮 = 中距离投篮 + 三分投篮），每项的成长速度为专项计划的62%。总体成长略多（124%对100%），但分摊在两项技能上。",
