  "Tous vos matchs de la saison, championnat et Coupe, groupés par mois. Les matchs se jouent tout seuls à l'heure prévue (championnat le mardi et le samedi à 20:00, Coupe le jeudi à 20:00) : connectez-vous pour les suivre en direct, ou laissez-les se dérouler sans vous.": "本赛季你的所有比赛（联赛和杯赛），按月分组。比赛会在预定时间自动进行（联赛在周二和周六 20:00，杯赛在周四 20:00）：你可以登录观看直播，也可以让比赛在你不在时自行进行。",
