  "Transmettez ce code aux managers Premium que vous voulez inviter, de n'importe quel pays ou division. Ils le saisissent dans l'onglet Ligues privées.": "把这个代码发给你想邀请的 Premium 经理，任何国家或级别均可。他们在“私人联赛”标签页中输入即可。",
