  "Trigramme déjà modifié récemment : prochain changement possible dans {0} jour{1}.": "球队缩写最近已修改过：{0} 天后可再次修改。",
  "Trigramme du club": "球队缩写",
  "Trigramme enregistré : {0}.": "球队缩写已保存：{0}。",
  "Trois catégories de places (gradins, tribune, loges), chacune avec son propre prix. Un prix plus élevé rapporte plus par spectateur, mais peut réduire l'affluence si les supporters jugent que ça ne vaut pas le coup.": "三类座位（普通看台、主看台、包厢），每类都有各自的价格。价格越高，每位观众带来的收入越多，但如果球迷觉得不值，可能会降低上座人数。",
  "trop élevés": "过高",
  "true": "true",
  "TS%": "TS%",
  "Tu as déjà utilisé ta pub du mois{0}. Passe Pro pour un accès illimité.": "你本月的广告次数已用完{0}。升级 Pro 即可无限使用。",
  "turnover": "turnover",
  "Tutoriel d'accueil": "新手教程",
