  "défense": "防守",
  "(tir à 3 points, mi-distance, lancer franc),": "（三分投篮、中距离、罚球）、",
  "meneurs": "组织",
  "(dribble, passe, création de tir, pénétration),": "（运球、传球、创造投篮、突破）、",
  "intérieurs": "内线",
  "(jeu intérieur, rebond, contre, défense intérieure) ou": "（内线进攻、篮板、盖帽、内线防守）或",
  "(défense extérieure, interceptions). Chaque semaine, tous les joueurs non blessés progressent un peu sur ces caractéristiques, qu'ils aient joué ou non, en plus de l'entraînement des fondamentaux. Moins sa spécialité compte de caractéristiques, plus chacune progresse vite. L'effet est surtout sensible chez les jeunes, il dépend aussi du poste et du gabarit de chaque joueur, et il est renforcé par l'entraîneur principal.": "（外线防守、抢断）。每周，所有未受伤的球员都会在这些属性上略有提升，无论是否上场，这是在基础训练之外的额外提升。专长涵盖的属性越少，每项属性提升越快。这一效果主要体现在年轻球员身上，也取决于每名球员的位置和身体条件，并会因主教练而增强。",
  "Entraîneur, entraîneur adjoint, analyste vidéo, recruteur, médecin, kiné : chacun a 5 niveaux, avec un coût et un effet croissants. L'analyste vidéo révèle par exemple certaines caractéristiques cachées des joueurs adverses avant un match, et le kiné réduit le risque de blessure.": "主教练、助理教练、录像分析师、球探、队医、理疗师：每个职位都有 5 个等级，费用和效果逐级递增。例如，录像分析师会在赛前揭示对方球员的某些隐藏属性，理疗师会降低受伤风险。",
  "staff médical": "医疗团队",
  "s'achète sur le même marché aux enchères, avec le même salaire qui grimpe chaque semaine. Le": "同样在这个竞拍市场上聘请，工资同样每周上涨。",
  "raccourcit la durée des nouvelles blessures. Le": "缩短新伤病的持续时间。",
  "suit tout l'effectif : la forme physique remonte plus vite chaque jour et le risque de blessure en match baisse (il s'ajoute à l'effet de la salle de musculation). Plus leur niveau est élevé, plus l'effet est fort.": "照顾全队：体能每天恢复更快，比赛中的受伤风险降低（与力量训练室的效果叠加）。等级越高，效果越强。",
