  ", décidées le lundi d'intersaison et appliquées à la reprise : le champion des play-offs de chaque championnat monte ; en face, le 10e descend, puis le 9e, puis le perdant du barrage (7e contre 8e), autant qu'il y a de championnats ouverts juste en dessous. Une prime de montée est versée au club promu.": "，在休赛期的周一决定，并在新赛季开始时生效：每个联赛的季后赛冠军升级；相应地，第 10 名降级，然后是第 9 名，然后是保级附加赛（第 7 名对第 8 名）的输家，降级数量取决于下一级已开放的联赛数量。升级的俱乐部会获得一笔升级奖金。",
  "(en bas du menu) : choisissez un pays (le vôtre par défaut) pour voir ses divisions ouvertes, son palmarès et les meilleurs joueurs de la saison. Pour afficher un autre championnat ou un club, tapez son nom dans la barre de recherche du haut (« II.2 », « Division III », un nom de club…) : classement, derniers résultats et effectif en lecture seule.": "（在菜单底部）：选择一个国家（默认为你的国家），查看其已开放的级别、荣誉榜和本赛季最佳球员。要查看其他联赛或俱乐部，请在顶部搜索栏中输入其名称（“II.2”、“Division III”、俱乐部名称……）：积分榜、最新赛果和只读阵容。",
