  "Dans les championnats par pays, c'est la": "在各国联赛中，这就是",
  ": tous les clubs du pays (512 au plus), avec des exempts au premier tour pour les divisions les plus hautes si le tableau n'est pas plein. Le club de la division inférieure part avec": "：该国所有俱乐部（最多 512 家）参加，如果对阵表未满，最高级别的球队首轮轮空。低级别的俱乐部开赛即获得",
  "+7 points par division d'écart": "每相差一个级别 +7 分",
  "(au plus +21), déjà au tableau d'affichage. Un adversaire d'un autre championnat se prépare comme les autres (Ordres, scouting) et sa fiche s'ouvre dans Planète Hoop. Chaque match de Coupe gagné rapporte une prime, de 50 000 € aux premiers tours à 400 000 € pour la finale. À l'intersaison, la": "（最多 +21），直接计入记分牌。来自其他联赛的对手与其他对手一样准备（指令、球探），其页面在篮球星球中打开。每赢一场杯赛都有奖金，从早期轮次的 50 000 € 到决赛的 400 000 €。在休赛期，",
  "oppose le samedi à 20:00 le champion de Division I au vainqueur de la Coupe (ou au finaliste si c'est le même club), en direct et avec le même handicap : 200 000 € pour le vainqueur.": "会在周六 20:00 让一级联赛冠军对阵杯赛冠军（如果是同一家俱乐部，则对阵杯赛亚军），现场直播，并采用相同的让分规则：冠军获得 200 000 €。",
  "Coupe nationale · {0} · saison {1} : tous les clubs du pays, un tour chaque jeudi. Le club de division inférieure part avec": "全国杯赛 · {0} · 第 {1} 赛季：该国所有俱乐部参加，每周四进行一轮。低级别的俱乐部开赛即获得",
  "(au plus +21), compris dans les scores.": "（最多 +21），已计入比分。",
