  "Atteindre 100 victoires de championnat avec son club.": "带领俱乐部取得 100 场联赛胜利。",
  "Longue absence": "长期缺席",
  ": sans aucune visite pendant 45 jours, votre club est confié à l'IA (effectif, nom et palmarès conservés). Reconnectez-vous à votre compte pour le récupérer, s'il n'a pas été repris entre-temps par un autre manager ; sinon un nouveau club vous est attribué.": "：连续 45 天没有任何访问，你的俱乐部将交由 AI 管理（保留阵容、名称和荣誉）。重新登录你的账户即可收回，前提是期间没有被其他经理接手；否则你将获得一家新俱乐部。",
  "Bon retour à {0} !": "欢迎回到{0}！",
  "Pendant votre absence, le club a été géré par l'IA. Vérifiez votre effectif, vos ordres et votre budget.": "你不在期间，俱乐部由 AI 管理。请检查你的阵容、指令和预算。",
  "Contre un club d'un autre championnat": "对阵其他联赛的俱乐部",
  ", même d'un autre pays : tapez son nom dans la recherche d'adversaire, les clubs du monde entier apparaissent sous ceux de votre ligue (drapeau et division). Mêmes règles : jour de repos des deux clubs, heure de Paris, invitation à accepter contre un manager (il est prévenu dans son fil d'actualité).": "，甚至是其他国家的：在对手搜索中输入其名称，来自世界各地的俱乐部会显示在你所在联赛的俱乐部下方（带国旗和级别）。规则相同：两家俱乐部都在休息日，采用巴黎时间，对阵经理时需要对方接受邀请（对方会在动态消息中收到通知）。",
  "Club d'un autre championnat ({0}) : l'amical se joue à la même heure (Paris) pour les deux clubs.": "其他联赛的俱乐部（{0}）：友谊赛对两家俱乐部来说都在同一时间（巴黎时间）进行。",
  "Autre championnat": "其他联赛",
  "Un des deux clubs a changé de championnat.": "两家俱乐部中有一家更换了联赛。",
  "Adversaire du même championnat : passez par la liste habituelle.": "同一联赛的对手：请使用常规列表。",
  "Monde entier": "全世界",
  "Mon pays": "我的国家",
  "Mon championnat": "我的联赛",
  "Marché mondial": "全球市场",
  ": les annonces de tous les championnats, dans tous les pays, apparaissent aussi (drapeau et division du vendeur sur la carte ; filtre « Monde entier », « Mon championnat » ou le pays de votre choix, avec une recherche). On y enchérit de la même façon ; le joueur rejoint votre club à la clôture de l'enchère. Les annonces des autres championnats se mettent à jour toutes les quelques minutes : si quelqu'un a surenchéri entre-temps, votre enchère est refusée et le prix actualisé.": "：所有国家、所有联赛的挂牌也会显示（卡片上有卖家的国旗和级别；可按“全世界”、“我的联赛”或任选国家筛选，并可搜索）。出价方式相同；竞拍结束时球员加入你的俱乐部。其他联赛的挂牌每隔几分钟更新一次：如果期间有人出价更高，你的出价会被拒绝，并更新价格。",
