  "récompenses": "奖项",
  ": MVP, 5 majeur (un joueur par poste), meilleur jeune (21 ans ou moins), 6e homme (un joueur surtout remplaçant) et meilleur défenseur, puis le": "：MVP、最佳阵容（每个位置一名球员）、最佳新秀（21 岁及以下）、最佳第六人（主要替补出场的球员）和最佳防守球员，然后在决赛后颁发",
  "(dans l'équipe championne) après la finale. Elles se calculent sur la saison régulière, pour les joueurs qui ont disputé au moins 40 % des journées, et s'affichent dans l'onglet Ligue.": "（从冠军球队中产生）。奖项基于常规赛计算，仅限出场至少 40% 比赛日的球员，并在“联赛”标签页中显示。",
  "À mi-saison, le dimanche à 20h, les 10 meilleurs joueurs du pays affrontent les 10 meilleurs étrangers lors du": "赛季中期，周日 20 点，本国 10 名最佳球员将对阵 10 名最佳外籍球员，参加",
  ", un match d'exhibition sans effet sur le classement ni sur la forme. La fiche de chaque joueur montre sa nationalité et sa": "，这是一场表演赛，不影响积分榜和体能。每名球员的资料页都会显示他的国籍和",
  "carrière": "生涯",
  "saison par saison, avec ses distinctions.": "（逐赛季显示，包括所获荣誉）。",
  "On y trouve aussi vos": "这里还有你的",
  "succès": "成就",
  "de manager (première victoire, séries, titres, salle pleine, jeune formé au club devenu titulaire...), avec une barre de progression pour ceux qui restent à débloquer. Les autres managers les voient, avec votre bilan et vos titres, dans le profil affiché sur la fiche de votre club.": "（首胜、连胜、冠军、球馆满座、青训球员成为首发……），尚未解锁的成就会显示进度条。其他经理可以在你俱乐部页面的个人资料中看到它们，以及你的战绩和冠军。",
