  "des deux clubs (aucun match officiel ce jour-là), à l'heure de votre choix, jusqu'à 3 semaines à l'avance, et un seul par jour. Une équipe CPU accepte tout de suite ; un autre manager reçoit un message privé et doit accepter avant l'heure du match.": "进行（两家俱乐部当天都没有正式比赛），时间由你选择，最多可提前 3 周安排，每天只能一场。CPU 球队会立即接受；其他经理会收到私信，需在比赛时间前接受。",
