  "Ces ordres valent pour tous vos matchs de ligue privée à venir, jamais pour les matchs officiels. Sans ordres enregistrés, la ligue privée se joue avec les ordres actuels du club.": "这些指令适用于你接下来所有的私人联赛比赛，绝不用于正式比赛。没有保存的指令时，私人联赛使用俱乐部当前的指令。",
