  "Seuls aujourd'hui et les jours des semaines à venir proposées peuvent être planifiés.": "只能安排今天以及所列未来几周的日子。",
  "Minutes de la semaine en cours (titulaire régulier ≈ 60 min).": "本周上场时间（常规首发≈60分钟）。",
  "Bilan du lundi": "周一总结",
  "joueurs suivis": "跟进球员",
