  "Physique × {0}": "体能 × {0}",
  "Blessé à l'entraînement": "训练中受伤",
  "{0} n'a joué que {1} min cette semaine sur {2} : son plan ne compte qu'à {3} %.": "{0}本周只上场{1}/{2}分钟：其计划仅按{3}%计算。",
  "Forme moyenne de l'équipe": "球队平均状态",
  "Plans individuels.": "个人计划。",
  "Chaque place de plan associe un joueur à un programme parmi les 13 fondamentaux (tir, passe, défense, etc.), quel que soit son poste. Le nombre de places dépend de l'entraîneur : 3 aux niveaux 1 et 2, 4 aux niveaux 3 et 4, 5 au niveau 5. Sans entraîneur, aucun fondamental n'est travaillé. L'entraînement se déclenche le lundi à 6h, heure de Paris.": "每个计划名额为一名球员指定13项基本功中的一个项目（投篮、传球、防守等），与其位置无关。名额数量取决于教练：1、2级为3个，3、4级为4个，5级为5个。没有教练则不训练任何基本功。训练在巴黎时间周一6点进行。",
  "Rendement.": "训练效率。",
  "Un joueur en plan doit avoir joué 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement, moins s'il a peu joué. L'âge (les jeunes apprennent plus vite), le gabarit, le niveau de l'entraîneur et l'intensité de la semaine font varier le rendement, affiché en % pour chaque joueur. Le poste n'a plus d'effet.": "计划内球员需在一周内（联赛、杯赛、季后赛和友谊赛）上场30分钟才能获得全额效率，上场少则效率降低。年龄（年轻人学得更快）、体型、教练等级和本周强度会影响效率，每名球员以百分比显示。位置不再有影响。",
  "Intensité.": "强度。",
  "Légère : progression plus lente, meilleure récupération. Normale. Intense : progression plus rapide, mais forme en baisse et petit risque de blessure pour les joueurs en plan.": "轻度：进步较慢，恢复更好。正常。高强度：进步更快，但计划内球员状态下降，并有小幅受伤风险。",
  "Plafond.": "上限。",
  "Chaque joueur a une marge de progression propre ; quand elle se réduit, la progression ralentit peu à peu, sans s'arrêter net. Un bon entraîneur repousse ce plafond. Quand un joueur ne progresse plus, le bilan du lundi propose un autre programme (bouton Appliquer).": "每名球员都有自己的提升空间；空间缩小时，进步会逐渐放缓，而不是戛然而止。好教练能提高这一上限。球员不再进步时，周一总结会建议换一个项目（“应用”按钮）。",
  "Spécialités de l'entraîneur.": "教练专长。",
  "Attaque ou Défense : programmes de cette famille plus efficaces. Physique : jours Physique plus efficaces. Jeunes : joueurs de 21 ans et moins, et académie, plus efficaces.": "进攻或防守：该类项目更有效。体能：体能日更有效。青年：21岁及以下球员和青训营训练更有效。",
  "Collectif.": "团队训练。",
  "Chaque jour sans match officiel, choisissez Tactique (un aspect précis : une priorité offensive, une défense ou un rythme ; plus il est neuf, plus il progresse vite), Récupération (forme en hausse pour tout l'effectif) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, la tactique n'est pas possible, mais les joueurs non retenus pour l'amical peuvent récupérer ou faire du physique.": "在每个无正式比赛的日子，选择战术（一个具体方面：进攻重点、防守或节奏；越新进步越快）、恢复（全队状态提升）或体能（小幅体能提升，主要针对年轻球员）。友谊赛当天不能练战术，但未入选友谊赛的球员可以恢复或练体能。",
  "Mental et parrainage.": "心理与师徒结对。",
  "Le mental progresse en partie tout seul, en partie avec les minutes jouées dans la semaine. Un jeune (22 ans au plus) associé à un vétéran (29 ans au moins) du même poste progresse plus vite au mental (2 parrainages au plus).": "心理属性一部分自然提升，一部分随本周上场时间提升。年轻球员（不超过22岁）与同位置老将（至少29岁）结对，心理成长更快（最多2对）。",
  "Chaque semaine (le lundi à 6h), vos joueurs en plan individuel travaillent le programme choisi pour eux parmi les 13 fondamentaux. Le nombre de places dépend de votre entraîneur (3 à 5) : sans entraîneur, pas de travail des fondamentaux. Le Physique et le Mental évoluent tout seuls, le Mental aussi avec les minutes jouées.": "每周（周一6点），有个人计划的球员会训练为其选定的13项基本功之一。名额数量取决于教练（3到5个）：没有教练就不训练基本功。身体和心理属性自然发展，心理属性也随上场时间提升。",
  "Un joueur en plan doit jouer 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement ; le poste n'a plus d'importance.": "计划内球员需在一周内（联赛、杯赛、季后赛和友谊赛）上场30分钟才能获得全额效率；位置不再重要。",
  "Chaque jour sans match, choisissez Tactique (un aspect précis), Récupération (forme +15) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, les joueurs non retenus peuvent récupérer ou faire du physique.": "每个无比赛日，选择战术（一个具体方面）、恢复（状态+15）或体能（小幅体能提升，主要针对年轻球员）。友谊赛当天，未入选的球员可以恢复或练体能。",
  "Une tactique neuve s'apprend vite (+12 par jour à 40), une tactique déjà maîtrisée beaucoup moins (+4 par jour à 95). Le détail est dans le Guide.": "新战术学得很快（40时每天+12），已掌握的战术则慢得多（95时每天+4）。详见指南。",
  // Entraînement v2 (retour utilisateur 2026-10-01).
  "+{0}/jour": "+{0}/天",
  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-8 %, en plus de l'alchimie.": "你的球队对每个战术选项的掌握程度各不相同：每个进攻重点、每种防守和每种节奏各有一个指标（在训练的“训练方向”菜单中可见）。你所使用选项的熟练度会在比赛中影响全队，最多 +/-8%，并且与化学反应叠加。",
  "sur cette option la fait monter à chaque jour de repos écoulé, selon son niveau : +12 par jour à 40, +9 à 60, +6 à 80, +4 à 95 (jamais un jour d'amical). Un": "该选项在每个休息日结束后提升，取决于当前水平：40时每天+12，60时+9，80时+6，95时+4（友谊赛当天不计）。一个",
  // Permaliens des joueurs (2026-10-01).
